    questions.append({
        "id": f"mcq-c8-{len(questions)+1:03d}",
        "chapterId": chapter_id,
        "subjectId": subject_id,
        "classId": "class-8",
        "topic": topic,
        "question": question,
        "options": options,
        "correctAnswerIndex": correct_idx,
        "explanation": explanation,
        "difficulty": difficulty,
        "category": category
    })

